{"command":"create","path":"/workspace/codebase/engine/src/args.rs","file_text":"//! Command line argument parsing, ported from the historical
//! `src/argsParser.js` module. The parsing rules (including the somewhat
//! unusual quirks around "unknown" options being passed through, converted
//! to lists, etc.) are preserved exactly so that CLI behavior is unchanged.

use serde_json::Value;
use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Process {
    None,
    Number,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Callback {
    Help,
    Version,
}

#[derive(Debug, Clone)]
pub struct OptionSpec {
    pub key: String,
    pub full: String,
    pub abbr: Option<char>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<Value>,
    pub default_help: Option<String>,
    pub choices: Option<Vec<Value>>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    pub display_index: i32,
    pub process: Process,
    pub callback: Option<Callback>,
}

impl OptionSpec {
    pub fn new(key: &str) -> Self {
        OptionSpec {
            key: key.to_string(),
            full: key.to_string(),
            abbr: None,
            flag: false,
            list: false,
            default: None,
            default_help: None,
            choices: None,
            help: None,
            metavar: None,
            display_index: 0,
            process: Process::None,
            callback: None,
        }
    }
}

pub struct ParseError {
    pub exit_code: i32,
    pub message: String,
}

fn throw_error(exit_code: i32, message: String, help_text: Option<&str>) -> ParseError {
    let message = match help_text {
        Some(help) => format!("{}\n\n---\n\n{}", message, help),
        None => message,
    };
    ParseError { exit_code, message }
}

fn format_value(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

fn format_option(option: &OptionSpec) -> String {
    let mut text = String::from("  ");
    text += &match option.abbr {
        Some(a) => format!("-{}, ", a),
        None => "    ".to_string(),
    };
    text += &format!("--{}{}", if option.flag { "(no-)" } else { "" }, option.full);
    if let Some(choices) = &option.choices {
        let joined = choices
            .iter()
            .map(format_value)
            .collect::<Vec<_>>()
            .join("|");
        text += &format!("={}", joined);
    } else if let Some(metavar) = &option.metavar {
        text += &format!("={}", metavar);
    }
    if option.list {
        text += " ...";
    }
    if option.default_help.is_some() || option.default.is_some() || option.help.is_some() {
        text += "  ";
        if text.len() < 32 {
            text += &" ".repeat(32 - text.len());
        }
        let text_length = text.len();
        if let Some(help) = &option.help {
            text += help;
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text += "\n";
            }
            let default_display = option
                .default_help
                .clone()
                .unwrap_or_else(|| format_value(option.default.as_ref().unwrap()));
            text += &format!("{}(default: {})", " ".repeat(text_length), default_display);
        }
    }
    text
}

pub fn get_help_text(options: &[OptionSpec]) -> String {
    let mut opts: Vec<&OptionSpec> = options.iter().collect();
    opts.sort_by_key(|o| o.display_index);

    let body = opts
        .iter()
        .map(|o| format_option(o))
        .collect::<Vec<_>>()
        .join("\n");

    let text = format!(
        "\nUsage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{}\n",
        body
    );
    text.trim_start().to_string()
}

fn is_option(value: &str) -> bool {
    value.starts_with('-')
}

pub struct ParseResult {
    pub positional_arguments: Vec<Value>,
    pub options: HashMap<String, Value>,
}

fn validate_options(
    parsed: &HashMap<String, Value>,
    options: &[OptionSpec],
) -> Result<(), ParseError> {
    let mut errors = Vec::new();
    for option in options {
        if let Some(choices) = &option.choices {
            let current = parsed.get(&option.key);
            let matches = current.map(|v| choices.contains(v)).unwrap_or(false);
            if !matches {
                let joined = choices
                    .iter()
                    .map(format_value)
                    .collect::<Vec<_>>()
                    .join(",");
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    option.full, joined
                ));
            }
        }
    }
    if !errors.is_empty() {
        return Err(throw_error(
            1,
            errors.join("\n"),
            Some(&get_help_text(options)),
        ));
    }
    Ok(())
}

/// Parses `.5` etc for unknown-option JSON-ish values, mirroring
/// `JSON.parse` fallback used for pass-through options in argsParser.js.
fn json_like(value: &str) -> Value {
    serde_json::from_str(value).unwrap_or_else(|_| Value::String(value.to_string()))
}

pub fn parse(
    options: &[OptionSpec],
    args: &[String],
) -> Result<ParseResult, ParseError> {
    // Build lookup maps: "--full" / "-a" / "--no-full" -> index into options
    // slice, or a dynamically created spec for unknown options.
    let mut by_flag: HashMap<String, usize> = HashMap::new();
    for (i, option) in options.iter().enumerate() {
        by_flag.insert(format!("--{}", option.full), i);
        if let Some(a) = option.abbr {
            by_flag.insert(format!("-{}", a), i);
        }
        if option.flag {
            by_flag.insert(format!("--no-{}", option.full), i);
        }
    }

    let mut parsed_options: HashMap<String, Value> = HashMap::new();
    for option in options {
        if let Some(default) = &option.default {
            parsed_options.insert(option.key.clone(), default.clone());
        } else if option.list {
            parsed_options.insert(option.key.clone(), Value::Array(vec![]));
        }
    }

    // Marker for "missing value" errors, tracked out-of-band since
    // serde_json::Value has no natural sentinel.
    let mut missing_value_keys: Vec<String> = Vec::new();

    let mut positional_arguments: Vec<Value> = Vec::new();

    let mut i = 0usize;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let (mut option_name, mut value) = match arg.find('=') {
                Some(idx) => (arg[..idx].to_string(), Some(arg[idx + 1..].to_string())),
                None => (arg.clone(), None),
            };

            if let Some(&idx) = by_flag.get(&option_name) {
                let option = &options[idx];
                if let Some(callback) = option.callback {
                    return Err(match callback {
                        Callback::Help => throw_error(0, get_help_text(options), None),
                        Callback::Version => throw_error(0, String::new(), None),
                    });
                }
                if option.flag {
                    let flag_value = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(v) = &value {
                        v == "1"
                    } else {
                        true
                    };
                    parsed_options.insert(option.key.clone(), Value::Bool(flag_value));
                } else {
                    if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    match value {
                        Some(v) => {
                            let processed = match option.process {
                                Process::Number => {
                                    v.parse::<f64>().map(json_number).unwrap_or(Value::String(v))
                                }
                                Process::None => Value::String(v),
                            };
                            if option.list {
                                parsed_options
                                    .entry(option.key.clone())
                                    .or_insert_with(|| Value::Array(vec![]));
                                if let Some(Value::Array(arr)) =
                                    parsed_options.get_mut(&option.key)
                                {
                                    arr.push(processed);
                                }
                            } else {
                                parsed_options.insert(option.key.clone(), processed);
                            }
                        }
                        None => {
                            missing_value_keys.push(option.key.clone());
                        }
                    }
                }
            } else {
                // Unknown option: passed through with best-effort semantics.
                let real_option_name = strip_option_prefix(&option_name);
                let has_current = parsed_options.contains_key(&real_option_name);
                let current_is_true = matches!(
                    parsed_options.get(&real_option_name),
                    Some(Value::Bool(true))
                );
                let is_list = has_current && !current_is_true;

                let next_looks_like_option = args
                    .get(i + 1)
                    .map(|s| is_option(s))
                    .unwrap_or(false);
                let is_flag = !has_current && value.is_none() && next_looks_like_option;

                if is_list {
                    if let Some(current) = parsed_options.get(&real_option_name).cloned() {
                        if !matches!(current, Value::Array(_)) {
                            let arr = if current == Value::Bool(true) {
                                Value::Array(vec![])
                            } else {
                                Value::Array(vec![current])
                            };
                            parsed_options.insert(real_option_name.clone(), arr);
                        }
                    }
                }

                if is_flag {
                    let flag_value = if option_name.starts_with("--no-") {
                        false
                    } else if let Some(v) = &value {
                        v == "1"
                    } else {
                        true
                    };
                    parsed_options.insert(real_option_name.clone(), Value::Bool(flag_value));
                } else {
                    if value.is_none() && i < args.len() - 1 && !is_option(&args[i + 1]) {
                        value = Some(args[i + 1].clone());
                        i += 1;
                    }
                    match value {
                        Some(v) => {
                            let processed = json_like(&v);
                            if is_list {
                                if let Some(Value::Array(arr)) =
                                    parsed_options.get_mut(&real_option_name)
                                {
                                    arr.push(processed);
                                } else {
                                    parsed_options
                                        .insert(real_option_name.clone(), Value::Array(vec![processed]));
                                }
                            } else {
                                parsed_options.insert(real_option_name.clone(), processed);
                            }
                        }
                        None => {
                            missing_value_keys.push(real_option_name.clone());
                        }
                    }
                }
                let _ = option_name;
            }
        } else {
            let value = if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                arg.parse::<f64>().map(json_number).unwrap_or_else(|_| Value::String(arg.clone()))
            } else {
                Value::String(arg.clone())
            };
            positional_arguments.push(value);
        }
        i += 1;
    }

    if let Some(key) = missing_value_keys.first() {
        let full = options
            .iter()
            .find(|o| &o.key == key)
            .map(|o| o.full.clone())
            .unwrap_or_else(|| key.clone());
        return Err(throw_error(
            1,
            format!("Missing value: --{} requires a value", full),
            Some(&get_help_text(options)),
        ));
    }

    validate_options(&parsed_options, options)?;

    Ok(ParseResult {
        positional_arguments,
        options: parsed_options,
    })
}

fn strip_option_prefix(name: &str) -> String {
    let stripped = name.trim_start_matches('-');
    if let Some(rest) = stripped.strip_prefix("no-") {
        rest.to_string()
    } else {
        stripped.to_string()
    }
}

fn json_number(f: f64) -> Value {
    if f.fract() == 0.0 && f.is_finite() {
        Value::Number(serde_json::Number::from(f as i64))
    } else {
        serde_json::Number::from_f64(f)
            .map(Value::Number)
            .unwrap_or(Value::Null)
    }
}
"}

{"command":"create","path":"/workspace/codebase/engine/src/ignore.rs","file_text":"//! Port of `src/ignoreFiles.js`. Implements gitignore-style pattern
//! collection and matching using a small glob-to-regex translator that
//! covers the subset of picomatch behavior jscodeshift relies on
//! (`*`, `**`, `?`, character classes, and `dot: true` matching).

use regex::Regex;
use std::fs;
use std::path::Path;

pub struct Ignores {
    matchers: Vec<Regex>,
}

impl Ignores {
    pub fn new() -> Self {
        Ignores { matchers: Vec::new() }
    }

    pub fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let mut patterns: Vec<String> = Vec::new();
        if !val.contains('/') {
            patterns.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            patterns.push(format!("**/{}**", val));
            patterns.push(format!("{}**", val));
        }
        patterns.push(val.to_string());

        for p in patterns {
            if let Some(re) = glob_to_regex(&p) {
                self.matchers.push(re);
            }
        }
    }

    pub fn add_from_input(&mut self, input: &[String]) {
        for pattern in input {
            self.add_pattern(pattern);
        }
    }

    pub fn add_from_file(&mut self, path: &str) -> std::io::Result<()> {
        let meta = fs::metadata(path)?;
        if meta.is_file() {
            let content = fs::read_to_string(path)?;
            for line in content.split(['\n']) {
                let line = line.strip_suffix('\r').unwrap_or(line);
                self.add_pattern(line);
            }
        }
        Ok(())
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        let normalized = strip_leading_traversal(path);
        if is_match(&self.matchers, path) {
            return true;
        }
        if normalized != path && is_match(&self.matchers, &normalized) {
            return true;
        }
        false
    }
}

fn is_match(matchers: &[Regex], path: &str) -> bool {
    matchers.iter().any(|re| re.is_match(path))
}

fn strip_leading_traversal(path: &str) -> String {
    let re = Regex::new(r"^(?:\.\.?[/\\])+").unwrap();
    re.replace(path, "").to_string()
}

/// Translates a (very small) subset of glob syntax used by picomatch's
/// default configuration into an anchored regular expression.
fn glob_to_regex(pattern: &str) -> Option<Regex> {
    let mut out = String::from("^");
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0usize;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    // `**` - match across path separators, including the
                    // adjoining slash so `a/**/b` also matches `a/b`.
                    let mut j = i + 2;
                    // consume optional trailing slash
                    if j < chars.len() && chars[j] == '/' {
                        j += 1;
                    }
                    out += "(?:.*/)?";
                    i = j;
                    continue;
                } else {
                    out += "[^/]*";
                }
            }
            '?' => out += "[^/]",
            '.' | '(' | ')' | '+' | '|' | '^' | '$' => {
                out.push('\\');
                out.push(c);
            }
            '[' => {
                // Pass character classes through mostly verbatim.
                let start = i;
                let mut j = i + 1;
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    j += 1;
                }
                while j < chars.len() && chars[j] != ']' {
                    j += 1;
                }
                if j < chars.len() {
                    let class: String = chars[start..=j].iter().collect();
                    let class = class.replacen('!', "^", 1);
                    out += &class;
                    i = j;
                } else {
                    out += "\\[";
                }
            }
            '{' => {
                // Brace expansion `{a,b}` -> `(?:a|b)`
                let start = i + 1;
                let mut j = start;
                while j < chars.len() && chars[j] != '}' {
                    j += 1;
                }
                if j < chars.len() {
                    let inner: String = chars[start..j].iter().collect();
                    let alts: Vec<String> = inner.split(',').map(escape_literal).collect();
                    out += "(?:";
                    out += &alts.join("|");
                    out += ")";
                    i = j;
                } else {
                    out += "\\{";
                }
            }
            _ => out.push_str(&escape_literal(&c.to_string())),
        }
        i += 1;
    }
    out.push('$');
    Regex::new(&out).ok()
}

fn escape_literal(s: &str) -> String {
    regex::escape(s)
}

#[allow(dead_code)]
pub fn strip_leading_traversal_pub(path: &Path) -> String {
    strip_leading_traversal(&path.to_string_lossy())
}
"}

