{"command":"create","path":"/workspace/codebase/engine/src/colors.rs","file_text":"//! Minimal reimplementation of the subset of `picocolors` used by the
//! runner: color support detection follows the same rules as the upstream
//! JS package (NO_COLOR / --no-color disable, FORCE_COLOR / --color / CI /
//! Windows / TTY enable).

use std::io::IsTerminal;

fn is_color_supported() -> bool {
    let args: Vec<String> = std::env::args().collect();
    let no_color = std::env::var("NO_COLOR").is_ok() || args.iter().any(|a| a == "--no-color");
    if no_color {
        return false;
    }
    let force_color = std::env::var("FORCE_COLOR").is_ok() || args.iter().any(|a| a == "--color");
    if force_color {
        return true;
    }
    if cfg!(windows) {
        return true;
    }
    let is_tty = std::io::stdout().is_terminal();
    let term_dumb = std::env::var("TERM").map(|t| t == "dumb").unwrap_or(false);
    if is_tty && !term_dumb {
        return true;
    }
    std::env::var("CI").is_ok()
}

fn wrap(open: &str, close: &str, input: &str) -> String {
    if is_color_supported() {
        format!("{}{}{}", open, input, close)
    } else {
        input.to_string()
    }
}

pub fn red(s: &str) -> String {
    wrap("\x1b[31m", "\x1b[39m", s)
}
pub fn green(s: &str) -> String {
    wrap("\x1b[32m", "\x1b[39m", s)
}
pub fn yellow(s: &str) -> String {
    wrap("\x1b[33m", "\x1b[39m", s)
}
pub fn blue(s: &str) -> String {
    wrap("\x1b[34m", "\x1b[39m", s)
}
pub fn white(s: &str) -> String {
    wrap("\x1b[37m", "\x1b[39m", s)
}
pub fn bg_green(s: &str) -> String {
    wrap("\x1b[42m", "\x1b[49m", s)
}
pub fn bg_yellow(s: &str) -> String {
    wrap("\x1b[43m", "\x1b[49m", s)
}
pub fn bg_red(s: &str) -> String {
    wrap("\x1b[41m", "\x1b[49m", s)
}
pub fn bg_blue(s: &str) -> String {
    wrap("\x1b[44m", "\x1b[49m", s)
}
"}

