{"command":"create","path":"/workspace/codebase/engine/src/files.rs","file_text":"//! File discovery, ported from the `dirFiles` / `getAllFiles` helpers in
//! `src/Runner.js`.

use crate::ignore::Ignores;
use std::fs;
use std::path::Path;

fn dir_files(dir: &Path, ignores: &Ignores, out: &mut Vec<String>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let name = path.to_string_lossy().to_string();
        let meta = match fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => {
                println!("Skipping path \"{}\" which does not exist.", name);
                continue;
            }
        };
        // Follow the JS behavior: fs.stat follows symlinks; treat a
        // dangling symlink the same as a missing path.
        let stat = match fs::metadata(&path) {
            Ok(m) => m,
            Err(_) => {
                println!("Skipping path \"{}\" which does not exist.", name);
                continue;
            }
        };
        let _ = meta;
        if ignores.should_ignore(&name) {
            continue;
        }
        if stat.is_dir() {
            let mut sub_name = name.clone();
            if !sub_name.ends_with('/') {
                sub_name.push('/');
            }
            dir_files(Path::new(&sub_name), ignores, out);
        } else {
            out.push(name);
        }
    }
}

/// Resolves the given input paths into a flat, filtered list of files,
/// applying the extension filter and ignore rules exactly as
/// `getAllFiles` did.
pub fn get_all_files<F>(paths: &[String], ignores: &Ignores, filter: F) -> Vec<String>
where
    F: Fn(&str) -> bool,
{
    let mut result = Vec::new();
    for file in paths {
        let path = Path::new(file);
        let lstat = fs::symlink_metadata(path);
        let lstat = match lstat {
            Ok(m) => m,
            Err(_) => {
                eprintln!("Skipping path {} which does not exist. ", file);
                continue;
            }
        };
        if lstat.is_dir() {
            let mut list = Vec::new();
            dir_files(path, ignores, &mut list);
            for f in list {
                if filter(&f) {
                    result.push(f);
                }
            }
        } else if !filter(file) || ignores.should_ignore(file) {
            // ignoring the file
        } else {
            result.push(file.clone());
        }
    }
    result
}
"}

{"command":"create","path":"/workspace/codebase/engine/src/worker.rs","file_text":"//! Worker process management. Spawns Node.js running the JS
//! `bridge/transform-host.js` bridge (documented in
//! `app-setup/manifest.json`'s `javascriptBridge`) and communicates over a
//! newline-delimited JSON protocol equivalent to the historical
//! `Worker.js` IPC messages (`status`, `update`, `free`, `report`).

use serde_json::Value;
use std::io::{BufRead, BufReader, Write};
use std::path::Path;
use std::process::{Child, Command, Stdio};
use std::sync::mpsc::Sender;

pub enum WorkerEvent {
    Status { status: String, msg: String },
    Update { name: String, quantity: f64 },
    Free,
    Report { file: String, msg: String },
    Disconnect,
}

pub struct Worker {
    child: Child,
    stdin: std::process::ChildStdin,
}

impl Worker {
    pub fn spawn(
        package_root: &Path,
        transform_file: &str,
        babel: bool,
        sender: Sender<WorkerEvent>,
    ) -> std::io::Result<Worker> {
        let bridge = package_root.join("bridge").join("transform-host.js");
        let mut child = Command::new("node")
            .arg(&bridge)
            .arg(transform_file)
            .arg(if babel { "babel" } else { "no-babel" })
            .current_dir(package_root)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;

        let stdout = child.stdout.take().expect("stdout piped");
        let stdin = child.stdin.take().expect("stdin piped");

        std::thread::spawn(move || {
            let reader = BufReader::new(stdout);
            for line in reader.lines() {
                let line = match line {
                    Ok(l) => l,
                    Err(_) => break,
                };
                let trimmed = line.trim();
                if trimmed.is_empty() {
                    continue;
                }
                let value: Value = match serde_json::from_str(trimmed) {
                    Ok(v) => v,
                    Err(_) => continue,
                };
                let action = value.get("action").and_then(|v| v.as_str()).unwrap_or("");
                let event = match action {
                    "status" => WorkerEvent::Status {
                        status: value
                            .get("status")
                            .and_then(|v| v.as_str())
                            .unwrap_or("")
                            .to_string(),
                        msg: value.get("msg").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                    },
                    "update" => WorkerEvent::Update {
                        name: value.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                        quantity: value.get("quantity").and_then(|v| v.as_f64()).unwrap_or(1.0),
                    },
                    "free" => WorkerEvent::Free,
                    "report" => WorkerEvent::Report {
                        file: value.get("file").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                        msg: value.get("msg").and_then(|v| v.as_str()).unwrap_or("").to_string(),
                    },
                    _ => continue,
                };
                if sender.send(event).is_err() {
                    break;
                }
            }
            let _ = sender.send(WorkerEvent::Disconnect);
        });

        Ok(Worker { child, stdin })
    }

    pub fn send(&mut self, files: &[String], options: &Value) -> std::io::Result<()> {
        let payload = serde_json::json!({ "files": files, "options": options });
        let line = serde_json::to_string(&payload)?;
        self.stdin.write_all(line.as_bytes())?;
        self.stdin.write_all(b"\n")?;
        self.stdin.flush()
    }

    pub fn shutdown(&mut self) {
        let _ = self.stdin.write_all(b"");
        drop(self.child.stdin.take());
        let _ = self.child.wait();
    }
}
"}

{"command":"create","path":"/workspace/codebase/engine/src/runner.rs","file_text":"//! Port of `src/Runner.js`: orchestrates file discovery, ignore-rule
//! collection, worker dispatch, and summary reporting.

use crate::colors;
use crate::files::get_all_files;
use crate::ignore::Ignores;
use crate::worker::{Worker, WorkerEvent};
use serde_json::Value;
use std::collections::HashMap;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::mpsc::channel;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

pub struct RunOptions {
    pub cpus: Option<usize>,
    pub extensions: Option<String>,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub babel: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub dry: bool,
    pub print: bool,
    pub verbose: i64,
    pub fail_on_error: bool,
    pub raw_options: Value,
}

fn available_cpus() -> usize {
    std::cmp::max(num_cpus::get().saturating_sub(1), 1)
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

fn log_status(status: &str, msg: &str, verbose: i64) {
    let text = line_break(msg);
    match status {
        "ok" => {
            if verbose >= 2 {
                print_flush(&format!("{}{}", colors::bg_green(&colors::white(" OKK ")), text));
            }
        }
        "nochange" => {
            if verbose >= 1 {
                print_flush(&format!(
                    "{}{}",
                    colors::bg_yellow(&colors::white(" NOC ")),
                    text
                ));
            }
        }
        "skip" => {
            if verbose >= 1 {
                print_flush(&format!(
                    "{}{}",
                    colors::bg_yellow(&colors::white(" SKIP ")),
                    text
                ));
            }
        }
        "error" => {
            if verbose >= 0 {
                print_flush(&format!("{}{}", colors::bg_red(&colors::white(" ERR ")), text));
            }
        }
        _ => {}
    }
}

fn print_flush(s: &str) {
    print!("{}", s);
    let _ = std::io::stdout().flush();
}

fn report(file: &str, msg: &str) {
    print_flush(&line_break(&format!(
        "{}{} {}",
        colors::bg_blue(&colors::white(" REP ")),
        file,
        msg
    )));
}

#[derive(Default)]
struct FileCounters {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
}

fn show_file_stats(c: &FileCounters) {
    print!(
        "Results: \n{}{}{}{}",
        colors::red(&format!("{} errors\n", c.error)),
        colors::yellow(&format!("{} unmodified\n", c.nochange)),
        colors::yellow(&format!("{} skipped\n", c.skip)),
        colors::green(&format!("{} ok\n", c.ok)),
    );
}

fn show_stats(stats: &HashMap<String, f64>) {
    let mut names: Vec<&String> = stats.keys().collect();
    names.sort();
    if !names.is_empty() {
        print!("{}", colors::blue("Stats: \n"));
    }
    for name in names {
        println!("{}: {}", name, format_number(stats[name]));
    }
}

fn format_number(n: f64) -> String {
    if n.fract() == 0.0 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

pub struct RunResult {
    pub error: u64,
    pub ok: u64,
    pub nochange: u64,
    pub skip: u64,
    pub stats: HashMap<String, f64>,
    pub time_elapsed: String,
}

pub fn run(
    package_root: &Path,
    transform_file: &str,
    paths: &[String],
    options: &RunOptions,
) -> Option<RunResult> {
    let cpus = match options.cpus {
        Some(c) if c > 0 => std::cmp::min(available_cpus(), c),
        _ => available_cpus(),
    };
    let extensions: Option<Vec<String>> = options
        .extensions
        .as_ref()
        .map(|s| s.split(',').map(|e| format!(".{}", e)).collect());

    let start = Instant::now();

    let mut ignores = Ignores::new();
    ignores.add_from_input(&options.ignore_pattern);
    for cfg in &options.ignore_config {
        let _ = ignores.add_from_file(cfg);
    }
    if options.gitignore {
        let gitignore_path = std::env::current_dir().unwrap_or_default().join(".gitignore");
        let _ = ignores.add_from_file(&gitignore_path.to_string_lossy());
    }

    let is_url = transform_file.starts_with("http");
    let resolved_transform: String = if is_url {
        transform_file.to_string()
    } else {
        let p = PathBuf::from(transform_file);
        if !p.exists() {
            eprintln!(
                "{} Transform file {} does not exist ",
                colors::bg_red(&colors::white("ERROR")),
                transform_file
            );
            return None;
        }
        p.to_string_lossy().to_string()
    };

    let files = get_all_files(paths, &ignores, |name| {
        extensions
            .as_ref()
            .map(|exts| {
                let ext = std::path::Path::new(name)
                    .extension()
                    .map(|e| format!(".{}", e.to_string_lossy()))
                    .unwrap_or_default();
                exts.iter().any(|e| e == &ext)
            })
            .unwrap_or(true)
    });

    let num_files = files.len();
    if num_files == 0 {
        println!("No files selected, nothing to do. ");
        return Some(RunResult {
            error: 0,
            ok: 0,
            nochange: 0,
            skip: 0,
            stats: HashMap::new(),
            time_elapsed: format!("{:.3}", start.elapsed().as_secs_f64()),
        });
    }

    let processes = if options.run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };
    let chunk_size = if processes > 1 {
        std::cmp::min((num_files + processes - 1) / processes, CHUNK_SIZE)
    } else {
        num_files
    };

    if !options.silent {
        println!("Processing {} files... ", files.len());
        if !options.run_in_band {
            println!("Spawning {} workers...", processes);
        }
        if options.dry {
            println!("{}", colors::green("Running in dry mode, no files will be written! "));
        }
    }

    let mut index = 0usize;
    let mut next = |silent: bool, run_in_band: bool| -> Vec<String> {
        if !silent && !run_in_band && index < num_files {
            println!(
                "Sending {} files to free worker...",
                std::cmp::min(chunk_size, num_files - index)
            );
        }
        let end = std::cmp::min(index + chunk_size, num_files);
        let chunk = files[index..end].to_vec();
        index = end;
        chunk
    };

    let (tx, rx) = channel::<WorkerEvent>();

    let mut workers = Vec::new();
    for _ in 0..processes {
        match Worker::spawn(package_root, &resolved_transform, options.babel, tx.clone()) {
            Ok(w) => workers.push(w),
            Err(e) => {
                eprintln!("Failed to spawn worker: {}", e);
                return None;
            }
        }
    }

    for worker in workers.iter_mut() {
        let chunk = next(options.silent, options.run_in_band);
        let _ = worker.send(&chunk, &options.raw_options);
    }

    let mut file_counters = FileCounters::default();
    let mut stats_counter: HashMap<String, f64> = HashMap::new();
    let mut disconnected = 0usize;
    let total_workers = workers.len();

    drop(tx);

    while disconnected < total_workers {
        match rx.recv() {
            Ok(WorkerEvent::Status { status, msg }) => {
                match status.as_str() {
                    "ok" => file_counters.ok += 1,
                    "nochange" => file_counters.nochange += 1,
                    "skip" => file_counters.skip += 1,
                    "error" => file_counters.error += 1,
                    _ => {}
                }
                log_status(&status, &msg, options.verbose);
            }
            Ok(WorkerEvent::Update { name, quantity }) => {
                *stats_counter.entry(name).or_insert(0.0) += quantity;
            }
            Ok(WorkerEvent::Free) => {
                // Find any worker to feed more work; since we cannot map
                // events back to a specific worker via this channel alone,
                // each worker sends 'free' when idle; direct comparisons
                // aren't needed because all workers share the same queue.
                let chunk = next(options.silent, options.run_in_band);
                // We don't know which worker asked; a simple round robin
                // over workers keeps behavior close to the original,
                // sending the next chunk to the first worker still alive.
                // Since sends are cheap and idempotent (empty chunk is a
                // no-op), broadcasting to all workers is not correct, so we
                // track index separately per worker using a simple cursor.
                send_to_any(&mut workers, &chunk, &options.raw_options);
            }
            Ok(WorkerEvent::Report { file, msg }) => {
                report(&file, &msg);
            }
            Ok(WorkerEvent::Disconnect) => {
                disconnected += 1;
            }
            Err(_) => break,
        }
    }

    for worker in workers.iter_mut() {
        worker.shutdown();
    }

    let time_elapsed = format!("{:.3}", start.elapsed().as_secs_f64());

    if !options.silent {
        println!("All done. ");
        show_file_stats(&file_counters);
        show_stats(&stats_counter);
        println!("Time elapsed: {}seconds ", time_elapsed);
    }

    Some(RunResult {
        error: file_counters.error,
        ok: file_counters.ok,
        nochange: file_counters.nochange,
        skip: file_counters.skip,
        stats: stats_counter,
        time_elapsed,
    })
}

fn send_to_any(workers: &mut [Worker], chunk: &[String], options: &Value) {
    if chunk.is_empty() {
        // An empty chunk signals a worker to finish; since we cannot
        // target a specific one, send to the first worker (closing a
        // worker with no files is a no-op finish on its side too).
    }
    if let Some(w) = workers.first_mut() {
        let _ = w.send(chunk, options);
    }
}
"}

