{"command":"create","path":"/workspace/codebase/engine/src/ignore.rs","file_text":"//! Port of `src/ignoreFiles.js`: builds a set of glob-style ignore
//! patterns (approximating gitignore semantics) and matches candidate
//! paths against them, mirroring `picomatch.isMatch(path, matchers, {dot:
//! true})` semantics for the subset of glob syntax jscodeshift relies on
//! (`*`, `**`, `?`, character classes, literal segments).

use regex::Regex;
use std::fs;

pub struct Ignores {
    matchers: Vec<Regex>,
}

impl Ignores {
    pub fn new() -> Self {
        Ignores { matchers: Vec::new() }
    }

    pub fn add_from_input(&mut self, patterns: &[String]) {
        for p in patterns {
            self.add_pattern(p);
        }
    }

    pub fn add_from_file(&mut self, path: &str) -> std::io::Result<()> {
        let meta = fs::metadata(path)?;
        if !meta.is_file() {
            return Ok(());
        }
        let content = fs::read_to_string(path)?;
        for line in content.split(['\n', '\r']).filter(|l| !l.is_empty()) {
            self.add_pattern(line);
        }
        Ok(())
    }

    fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val;
        if !pattern.contains('/') {
            self.push_glob(&format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.push_glob(&format!("**/{}**", pattern));
            self.push_glob(&format!("{}**", pattern));
        }
        self.push_glob(pattern);
    }

    fn push_glob(&mut self, glob: &str) {
        if let Some(re) = glob_to_regex(glob) {
            self.matchers.push(re);
        }
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        if self.matchers.is_empty() {
            return false;
        }
        if self.matches(path) {
            return true;
        }
        let normalized = strip_leading_traversal(path);
        if normalized != path && self.matches(&normalized) {
            return true;
        }
        false
    }

    fn matches(&self, path: &str) -> bool {
        self.matchers.iter().any(|re| re.is_match(path))
    }
}

fn strip_leading_traversal(path: &str) -> String {
    let mut s = path;
    loop {
        if let Some(rest) = s.strip_prefix("../") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix("./") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix("..\\") {
            s = rest;
        } else if let Some(rest) = s.strip_prefix(".\\") {
            s = rest;
        } else {
            break;
        }
    }
    s.to_string()
}

/// Translates a picomatch-style glob into an anchored regular expression.
/// Supports `**`, `*`, `?`, `[...]` character classes, and literal path
/// segments separated by `/`; `dot: true` semantics mean `*`/`**` also
/// match leading dots.
fn glob_to_regex(glob: &str) -> Option<Regex> {
    let mut re = String::from("^");
    let chars: Vec<char> = glob.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        match c {
            '*' => {
                if i + 1 < chars.len() && chars[i + 1] == '*' {
                    // `**` - match across path separators, including empty.
                    let mut j = i + 2;
                    // consume an optional following slash: **/ means zero or more segments
                    if j < chars.len() && chars[j] == '/' {
                        re.push_str("(?:.*/)?");
                        j += 1;
                    } else {
                        re.push_str(".*");
                    }
                    i = j;
                    continue;
                } else {
                    re.push_str("[^/]*");
                }
            }
            '?' => re.push_str("[^/]"),
            '[' => {
                let mut j = i + 1;
                let mut class = String::from("[");
                if j < chars.len() && (chars[j] == '!' || chars[j] == '^') {
                    class.push('^');
                    j += 1;
                }
                while j < chars.len() && chars[j] != ']' {
                    class.push(chars[j]);
                    j += 1;
                }
                class.push(']');
                re.push_str(&class);
                i = j + 1;
                continue;
            }
            '.' | '+' | '(' | ')' | '|' | '^' | '$' | '{' | '}' | '\\' => {
                re.push('\\');
                re.push(c);
            }
            _ => re.push(c),
        }
        i += 1;
    }
    re.push('$');
    Regex::new(&re).ok()
}
"}

