{"command":"create","path":"/workspace/codebase/engine/src/main.rs","file_text":"//! Entry point for the jscodeshift Rust engine. Ported from
//! `bin/jscodeshift.js`: parses CLI options, resolves the transform +
//! target files, and delegates to the (ported) `Runner`.

mod args;
mod cli;
mod colors;
mod files;
mod ignore;
mod runner;
mod versions;
mod worker;

use serde_json::Value;
use std::io::Read;
use std::path::PathBuf;

fn package_root() -> PathBuf {
    // The engine binary lives at `<root>/engine/target/.../jscodeshift-engine`.
    // We instead resolve the package root relative to the compiled binary's
    // manifest directory at build time, falling back to CARGO_MANIFEST_DIR's
    // parent when running via `cargo run`.
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    manifest_dir
        .parent()
        .map(|p| p.to_path_buf())
        .unwrap_or(manifest_dir)
}

fn version_text(root: &std::path::Path) -> String {
    let pkg_version = read_pkg_version(root).unwrap_or_else(|| "unknown".to_string());
    let babel = versions::package_version(root, "@babel/core").unwrap_or_else(|| "unknown".to_string());
    let babylon = versions::package_version(root, "@babel/parser").unwrap_or_else(|| "unknown".to_string());
    let flow = versions::package_version(root, "flow-parser").unwrap_or_else(|| "unknown".to_string());
    let recast = versions::package_version(root, "recast").unwrap_or_else(|| "unknown".to_string());
    format!(
        "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n\n",
        pkg_version, babel, babylon, flow, recast
    )
}

fn read_pkg_version(root: &std::path::Path) -> Option<String> {
    let content = std::fs::read_to_string(root.join("package.json")).ok()?;
    let value: Value = serde_json::from_str(&content).ok()?;
    value.get("version")?.as_str().map(|s| s.to_string())
}

fn value_to_string(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        other => other.to_string(),
    }
}

fn value_list(v: Option<&Value>) -> Vec<String> {
    match v {
        Some(Value::Array(arr)) => arr.iter().map(value_to_string).collect(),
        Some(other) => vec![value_to_string(other)],
        None => Vec::new(),
    }
}

fn main() {
    let root = package_root();
    let options_spec = cli::build_options();

    let raw_args: Vec<String> = std::env::args().skip(1).collect();

    let parsed = match args::parse(&options_spec, &raw_args) {
        Ok(p) => p,
        Err(e) => {
            if let Some(cb) = e.callback {
                let text = match cb {
                    args::Callback::Version => version_text(&root),
                    args::Callback::Help => args::get_help_text(&options_spec),
                };
                print!("{}", text);
                std::process::exit(0);
            }
            let exit_code = e.exit_code;
            if exit_code != 0 {
                eprint!("{}", e.message);
            } else {
                print!("{}", e.message);
            }
            std::process::exit(exit_code);
        }
    };

    let options = parsed.options;
    let stdin_flag = matches!(options.get("stdin"), Some(Value::Bool(true)));

    if parsed.positional_arguments.is_empty() && !stdin_flag {
        let help = args::get_help_text(&options_spec);
        eprint!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            help
        );
        std::process::exit(1);
    }

    let transform = options
        .get("transform")
        .map(value_to_string)
        .unwrap_or_else(|| "./transform.js".to_string());

    let run_paths = |paths: Vec<String>, options: &std::collections::HashMap<String, Value>| {
        let resolved = if transform.starts_with("http") || transform.starts_with("https") {
            transform.clone()
        } else {
            std::fs::canonicalize(&transform)
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or_else(|_| transform.clone())
        };

        let cpus = options.get("cpus").and_then(|v| v.as_f64()).map(|f| f as usize);
        let extensions = options.get("extensions").map(value_to_string);
        let babel = matches!(options.get("babel"), Some(Value::Bool(true)) | None);
        let dry = matches!(options.get("dry"), Some(Value::Bool(true)));
        let print = matches!(options.get("print"), Some(Value::Bool(true)));
        let run_in_band = matches!(options.get("runInBand"), Some(Value::Bool(true)));
        let silent = matches!(options.get("silent"), Some(Value::Bool(true)));
        let fail_on_error = matches!(options.get("failOnError"), Some(Value::Bool(true)));
        let verbose = options.get("verbose").and_then(|v| v.as_i64()).unwrap_or(0);
        let ignore_pattern = value_list(options.get("ignorePattern"));
        let ignore_config = value_list(options.get("ignoreConfig"));
        let gitignore = matches!(options.get("gitignore"), Some(Value::Bool(true)));

        let raw_options: Value = serde_json::to_value(options).unwrap_or(Value::Null);

        let run_options = runner::RunOptions {
            cpus,
            extensions,
            ignore_pattern,
            ignore_config,
            gitignore,
            babel,
            run_in_band,
            silent,
            dry,
            print,
            verbose,
            fail_on_error,
            raw_options,
        };

        let result = runner::run(&root, &resolved, &paths, &run_options);
        if let Some(res) = result {
            if run_options.fail_on_error && res.error > 0 {
                std::process::exit(1);
            }
        }
    };

    if stdin_flag {
        let mut buffer = String::new();
        let _ = std::io::stdin().read_to_string(&mut buffer);
        let paths: Vec<String> = buffer.split('\n').map(|s| s.to_string()).collect();
        run_paths(paths, &options);
    } else {
        let paths: Vec<String> = parsed
            .positional_arguments
            .iter()
            .map(value_to_string)
            .collect();
        run_paths(paths, &options);
    }
}
