/// Lexical equivalent of Node's `path.resolve(p)`: resolves `p` against
/// the current working directory and normalizes `.`/`..` segments,
/// without touching the filesystem (no symlink resolution, no existence
/// check), matching `bin/jscodeshift.js`'s use of `path.resolve`.
fn path_resolve(p: &str) -> String {
    let cwd = std::env::current_dir().unwrap_or_default();
    let joined = if PathBuf::from(p).is_absolute() {
        PathBuf::from(p)
    } else {
        cwd.join(p)
    };

    let mut out: Vec<std::ffi::OsString> = Vec::new();
    for comp in joined.components() {
        use std::path::Component::*;
        match comp {
            Prefix(_) | RootDir => {
                out.clear();
                out.push(comp.as_os_str().to_os_string());
            }
            CurDir => {}
            ParentDir => {
                if out.len() > 1 {
                    out.pop();
                }
            }
            Normal(seg) => out.push(seg.to_os_string()),
        }
    }
    let mut result = PathBuf::new();
    for seg in &out {
        result.push(seg);
    }
    result.to_string_lossy().to_string()
}"}

